mapper.select:
SELECT ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ROUND(NVL(T5.FINISH_AMT,0)/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 transactioncom, ETR_ENTRUST.INV_MANAGER_ID invManagerId, (SELECT real_name FROM SYS_USER WHERE user_name = ETR_ENTRUST.INV_MANAGER_ID) invManagerName, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, (select sec_acct_name from stl_sec_acct_info where stl_sec_acct_info.sec_acct_id = ETR_ENTRUST_ADD.SEC_ACCT_ID) as secAcctName, ETR_ENTRUST.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, ETR_ENTRUST_ADD.SETTLE_SPREED settleSpreed, ETR_ENTRUST.PS ps, ETR_ENTRUST.ENTRUST_NUM/100 entrustNum, NVL(T5.FINISH_AMT,0)/10000 finishAmt, NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - NVL(T5.FINISH_AMT,0)/10000 avaNum, (NVL(ETR_ENTRUST.ENTRUST_NUM,0) /100 -NVL(T5.FINISH_AMT, 0)/10000 ) AS entrustAvaNum, ETR_ENTRUST.PRICE price, ETR_ENTRUST_ADD.MATURE_YIELD * 100 matureYield, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST_ADD.QUOTE_TYPE quoteType, ETR_ENTRUST.BUSINESS_MODEL businessModel,
MST_CFETS_CUSTOMER_INFO.PARTY_ID mySide,
MST_CFETS_CUSTOMER_INFO.PARTY_ABBR mySideAbbr,
(SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = '${loginUserId}' AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID) ) mySideTrader,
(SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_NAME FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = '${loginUserId}' AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID) ) mySideTraderName,
MST_CFETS_CI.PARTY_ID counterId,
CASE WHEN MST_CFETS_CI.PARTY_ABBR IS NOT NULL THEN MST_CFETS_CI.PARTY_ABBR ELSE MST_CFETS_CI2.PARTY_NAME END counterName,
ETR_ENTRUST.COUNTER_TRADER counterTrader,
MST_CFETS_CT.TRADER_NAME counterTraderName, ETR_ENTRUST_ADD.EXER_YIELD * 100 exerYield, NVL(ETR_ENTRUST_ADD.CAL_MODE,DECODE(ETR_ENTRUST_ADD.CALCULATE_FIELD,'price','01','matureYield','02','exerYield','03','01')) calculateField, FIN_PRODUCT.IS_RIGHT isRight, FIN_PRODUCT_TYPE.TYPE_4 assetTypeOne, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.CCY settleCcy, IBU_PORTFOLIO_ACCT_RELA.CFETS_ACCT_TYPE secAcctSource, ROUND(NVL(C.totalShareAmt,nvl(C2.totalShareAmt,0))/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 tradeFinishPercent, ETR_ENTRUST.PRICE_MODEL priceModel, ETR_ENTRUST_ADD.SEC_ACCT_ID secManageAcctId, PA_PTL_PORTFOLIO.PORTFOLIO_SERIES portfolioSeries FROM ETR_ENTRUST INNER JOIN PTL_PORTFOLIO ON ETR_ENTRUST.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = PA_PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN ETR_DISTRIBUTE ON ETR_ENTRUST.ENTRUST_ID = ETR_DISTRIBUTE.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN FIN_PRODUCT ON ETR_ENTRUST.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ON ETR_ENTRUST.PORTFOLIO_ID = IBU_PORTFOLIO_ACCT_RELA.PORTFOLIO_ID AND IBU_PORTFOLIO_ACCT_RELA.CFETS_ACCT_TYPE = '01' LEFT JOIN MST_CFETS_CUSTOMER_INFO ON IBU_PORTFOLIO_ACCT_RELA.PARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID LEFT JOIN SYS_USER ON ETR_ENTRUST.CREATE_USER = SYS_USER.USER_NAME LEFT JOIN SYS_USER_ADD ON SYS_USER.USER_ID = SYS_USER_ADD.USER_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER ON SYS_USER_ADD.IBU_TRADER = MST_CFETS_CUSTOMER_TRADER.TRADER_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MST_CFETS_CT ON MST_CFETS_CT.TRADER_ID = ETR_ENTRUST.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = ETR_ENTRUST.COUNTER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MST_CFETS_CI ON MST_CFETS_CI.PARTY_NAME = MCP.COUNTER_NAME LEFT JOIN MST_CFETS_CUSTOMER_INFO MST_CFETS_CI2 ON MST_CFETS_CI2.PARTY_ID = ETR_ENTRUST.COUNTER_ID
LEFT JOIN (SELECT C.ENTRUST_ID, SUM(nvl(C.SHARE_AMT, 0)) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE C ON A.QUOTE_ID = C.QUOTE_ID WHERE B.TRADE_STATUS = '07' GROUP BY C.ENTRUST_ID) C ON C.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT A.ENTRUST_ID, nvl(A.SHARE_AMT, 0) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID WHERE B.TRADE_STATUS = '07') C2 ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ENTRUST_STATUS')D ON ETR_ENTRUST.ENTRUST_STATUS = D.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'PS')E ON ETR_ENTRUST.PS = E.ITEM_CODE
WHERE ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2} AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket} AND ETR_ENTRUST.TRADE_MARKET_MODE = #{tradeMarketMode} AND ETR_ENTRUST.PS IN (#{psT01}, #{psT02}) AND ETR_ENTRUST.ENTRUST_STATUS IN (#{entrustStatusUnAccept}, #{entrustStatusAccept}, #{entrustStatusComple})
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusUnAccept}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < NVL(ETR_ENTRUST.ENTRUST_NUM, 0) * 100
AND ((ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} and NVL(T5.FINISH_AMT,0) >= NVL(ETR_ENTRUST.ENTRUST_NUM, 0) * 100) or ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusComple})
AND ETR_ENTRUST.VDATE <= to_date(#{platDate}, 'yyyy-MM-dd') AND ETR_ENTRUST.MDATE >= to_date(#{platDate}, 'yyyy-MM-dd')
AND ETR_ENTRUST.VDATE <= to_date(#{entrustDateStart}, 'yyyy-MM-dd') AND ETR_ENTRUST.MDATE <= to_date(#{entrustDateStart}, 'yyyy-MM-dd')
AND ETR_ENTRUST.VDATE >= to_date(#{entrustDateEnd}, 'yyyy-MM-dd') AND ETR_ENTRUST.MDATE >= to_date(#{entrustDateEnd}, 'yyyy-MM-dd')
AND ETR_ENTRUST.PORTFOLIO_ID IN
#{item}
AND ETR_ENTRUST.FINPROD_ID IN
#{item}
AND ETR_ENTRUST.PS = #{ps}
AND DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpreed}
AND ETR_ENTRUST.INV_MANAGER_ID IN
#{item}
AND ETR_ENTRUST.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < NVL(ETR_ENTRUST.ENTRUST_NUM, 0) * 100
AND IBU_PORTFOLIO_ACCT_RELA.PARTY_ID = #{mySide}
AND ETR_DISTRIBUTE.TRADER = #{loginUserId}
AND STL_SEC_ACCT_INFO.SEC_ACCT_SOURCE = #{secAcctSource}
AND (SYS_USER.USER_NAME LIKE '%' || #{keywords} || '%' OR SYS_USER.REAL_NAME LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST.ENTRUST_STATUS like '%' || #{keywords} || '%' OR D.ITEM_VALUE LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST.PORTFOLIO_ID LIKE '%' || #{keywords} || '%' OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST.FINPROD_ID LIKE '%' || #{keywords} || '%' OR FIN_PRODUCT.FINPROD_ABBR LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST_ADD.SEC_ACCT_ID LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST.PS LIKE '%' || #{keywords} || '%' OR E.ITEM_VALUE LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST_ADD.SETTLE_SPREED LIKE '%' || decode(#{keywords},'T+0','0','T+1','1','T+2','2',#{keywords}) || '%' OR ETR_ENTRUST.PRICE LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST_ADD.MATURE_YIELD LIKE '%' || #{keywords} || '%' OR MST_CFETS_CI.PARTY_ABBR LIKE '%' || #{keywords} || '%' OR MST_CFETS_CT.TRADER_NAME LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST.VDATE LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST.MDATE LIKE '%' || #{keywords} || '%' OR ETR_ENTRUST.ENTRUST_ID LIKE '%' || #{keywords} || '%')
and ETR_ENTRUST.ENTRUST_ID in
#{item}
and ETR_ENTRUST.ENTRUST_ID not in
#{item}
order by ETR_ENTRUST.FINPROD_ID,ETR_ENTRUST_ADD.SETTLE_SPREED,ETR_ENTRUST.PS desc

SELECT ETR_ENTRUST.ENTRUST_ID id, ETR_ENTRUST.ENTRUST_ID text FROM ETR_ENTRUST LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO ON ETR_ENTRUST_ADD.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ON ETR_ENTRUST.PORTFOLIO_ID = IBU_PORTFOLIO_ACCT_RELA.PORTFOLIO_ID AND IBU_PORTFOLIO_ACCT_RELA.CFETS_ACCT_TYPE = #{secAcctSource_01} LEFT JOIN FIN_PRODUCT ON ETR_ENTRUST.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN ETR_DISTRIBUTE ON ETR_ENTRUST.ENTRUST_ID = ETR_DISTRIBUTE.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID WHERE ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2} and ETR_ENTRUST.TRADE_MARKET = #{tradeMarket} and ETR_ENTRUST.TRADE_MARKET_MODE = #{tradeMarketMode} and ETR_ENTRUST.PS IN (#{psT01}, #{psT02})
and ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND (ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{param},'%')) or ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{param},'%')))
and ETR_ENTRUST.ENTRUST_ID = #{initValue}
and ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < NVL(ETR_ENTRUST.ENTRUST_NUM, 0) * 100
AND ETR_DISTRIBUTE.TRADER = #{loginUserId}
AND ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{search},'%'))
and ETR_ENTRUST.VDATE <= to_date(#{platDate}, 'yyyy-MM-dd') and ETR_ENTRUST.MDATE >= to_date(#{platDate}, 'yyyy-MM-dd')
AND NVL(T5.FINISH_AMT,0) < NVL(ETR_ENTRUST.ENTRUST_NUM, 0) * 100
AND STL_SEC_ACCT_INFO.SEC_ACCT_SOURCE = #{secAcctSource}
AND IBU_PORTFOLIO_ACCT_RELA.PARTY_ID = #{mySide}
AND ETR_ENTRUST.FINPROD_ID = #{finprodId}
AND (ETR_ENTRUST.FINPROD_ID = #{finprodName} OR FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodName})
AND ETR_ENTRUST.PS = #{ps}
AND DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpreed}

SELECT ETR_ENTRUST.ENTRUST_ID code, ETR_ENTRUST.ENTRUST_ID name FROM ETR_ENTRUST LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO ON ETR_ENTRUST_ADD.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ON ETR_ENTRUST.PORTFOLIO_ID = IBU_PORTFOLIO_ACCT_RELA.PORTFOLIO_ID AND IBU_PORTFOLIO_ACCT_RELA.CFETS_ACCT_TYPE = #{secAcctSource_01} LEFT JOIN FIN_PRODUCT ON ETR_ENTRUST.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN ETR_DISTRIBUTE ON ETR_ENTRUST.ENTRUST_ID = ETR_DISTRIBUTE.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID WHERE ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2} and ETR_ENTRUST.TRADE_MARKET = #{tradeMarket} and ETR_ENTRUST.TRADE_MARKET_MODE = #{tradeMarketMode} and ETR_ENTRUST.PS IN (#{psT01}, #{psT02})
and ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND (ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{param},'%')) or ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{param},'%')))
and ETR_ENTRUST.ENTRUST_ID = #{initValue}
and ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < NVL(ETR_ENTRUST.ENTRUST_NUM, 0) * 100
AND ETR_DISTRIBUTE.TRADER = #{loginUserId}
AND ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{search},'%'))
and ETR_ENTRUST.VDATE <= to_date(#{platDate}, 'yyyy-MM-dd') and ETR_ENTRUST.MDATE >= to_date(#{platDate}, 'yyyy-MM-dd')
AND NVL(T5.FINISH_AMT,0) < NVL(ETR_ENTRUST.ENTRUST_NUM, 0) * 100
AND STL_SEC_ACCT_INFO.SEC_ACCT_SOURCE = #{secAcctSource}
AND IBU_PORTFOLIO_ACCT_RELA.PARTY_ID = #{mySide}
AND ETR_ENTRUST.FINPROD_ID = #{finprodId}
AND (ETR_ENTRUST.FINPROD_ID = #{finprodName} OR FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodName})
AND ETR_ENTRUST.PS = #{ps}
AND DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpreed}

SELECT
    SUM(NVL(ETR_QUOTE_FINISH_STATUS.FINISH_AMT, 0))
FROM
    ETR_QUOTE_FINISH_STATUS


		and ENTRUST_ID = #{entrustId}


		and QUOTE_ID != #{quoteId}

        select
        	to_char(CDATE, 'yyyy-MM-dd') as HOLIDATE
        from
        	VAL_VW_MST_HOLIDAY
        where
        	IS_HOLIDAY > 0

		  		and CDATE >= #{startDate, jdbcType=DATE}


		  		and CDATE <= #{endDate, jdbcType=DATE}


		  		and TRADE_CALENDAR_ID = #{dealCalId}

SELECT IQER.QUOTE_ID, IQER.FPRICE_AMT, A.ENTRUST_ID AS entrustId, A.PRICE AS price, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, (NVL(A.ENTRUST_NUM,0) /100 -NVL(T5.FINISH_AMT, 0)/10000 ) AS entrustAvaNum, IQER.SHARE_AMT/100 as avaNum, IQER.DEAL_FEE_AMT DEAL_FEE_AMT, IQER.SETT_FEE_AMT SETT_FEE_AMT, IQER.CPRICE_AMT, IQER.INT_AMT, A.PRICE_MODEL, A.BUSINESS_MODEL, T2.SEC_ACCT_NAME secAcctName, T1.SEC_ACCT_ID secManageAcctId, T1.EXER_YIELD , T1.MATURE_YIELD FROM IBU_QUOTE_ETR_RE IQER LEFT JOIN ETR_ENTRUST A ON A.ENTRUST_ID = IQER.ENTRUST_ID INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T1 ON T1.ENTRUST_ID = A.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO T2 ON T2.SEC_ACCT_ID = T1.SEC_ACCT_ID
and IQER.QUOTE_ID = #{quoteId}
union all SELECT IQER.QUOTE_ID, IQER.FPRICE_AMT, A.ENTRUST_ID AS entrustId, A.PRICE AS price, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, (NVL(A.ENTRUST_NUM,0) /100 -NVL(T5.FINISH_AMT, 0)/10000 ) AS entrustAvaNum, IQER.SHARE_AMT/100 as avaNum, IQER.DEAL_FEE_AMT DEAL_FEE_AMT, IQER.SETT_FEE_AMT SETT_FEE_AMT, IQER.CPRICE_AMT, IQER.INT_AMT, A.PRICE_MODEL, A.BUSINESS_MODEL, T2.SEC_ACCT_NAME, T1.SEC_ACCT_ID secManageAcctId, T1.EXER_YIELD , T1.MATURE_YIELD FROM WFL_IBU_QUOTE_ETR_RE IQER LEFT JOIN ETR_ENTRUST A ON A.ENTRUST_ID = IQER.ENTRUST_ID INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T1 ON T1.ENTRUST_ID = A.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO T2 ON T2.SEC_ACCT_ID = T1.SEC_ACCT_ID
and IQER.QUOTE_ID = #{quoteId}

SELECT IQER.QUOTE_ID, IQER.FPRICE_AMT, A.ENTRUST_ID AS entrustId, A.PRICE AS price, C.FULL_PRICE unitFprice, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, (NVL(A.ENTRUST_NUM,0) /100 -NVL(T5.FINISH_AMT, 0)/10000 ) AS entrustAvaNum, IQER.SHARE_AMT/100 as avaNum, IQER.DEAL_FEE_AMT DEAL_FEE_AMT, IQER.SETT_FEE_AMT SETT_FEE_AMT, IQER.CPRICE_AMT, IQER.FPRICE_AMT, IQER.INT_AMT, IQER.OUR_SHARE_AMT, IQER.LENDIN_SHARE_AMT, A.PRICE_MODEL , A.BUSINESS_MODEL, C.MATURE_YIELD, C.EXER_YIELD, D.SEC_ACCT_NAME FROM IBU_QUOTE_ETR_RE IQER LEFT JOIN ETR_ENTRUST A ON A.ENTRUST_ID = IQER.ENTRUST_ID INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD C ON A.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO D ON D.SEC_ACCT_ID = C.SEC_ACCT_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID
not exists (select 1 from wfl_IBU_QUOTE_ETR_RE wiqer where wiqer.quote_id = IQER.QUOTE_ID)
and IQER.QUOTE_ID = #{quoteId}
union all SELECT IQER.QUOTE_ID, IQER.FPRICE_AMT, A.ENTRUST_ID AS entrustId, A.PRICE AS price, C.FULL_PRICE unitFprice, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, (NVL(A.ENTRUST_NUM,0) /100 -NVL(T5.FINISH_AMT, 0)/10000 ) AS entrustAvaNum, IQER.SHARE_AMT/100 as avaNum, IQER.DEAL_FEE_AMT DEAL_FEE_AMT, IQER.SETT_FEE_AMT SETT_FEE_AMT, IQER.CPRICE_AMT, IQER.FPRICE_AMT, IQER.INT_AMT, IQER.OUR_SHARE_AMT, IQER.LENDIN_SHARE_AMT, A.PRICE_MODEL , A.BUSINESS_MODEL, C.MATURE_YIELD, C.EXER_YIELD, D.SEC_ACCT_NAME FROM WFL_IBU_QUOTE_ETR_RE IQER LEFT JOIN ETR_ENTRUST A ON A.ENTRUST_ID = IQER.ENTRUST_ID INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD C ON A.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO D ON D.SEC_ACCT_ID = C.SEC_ACCT_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID
and IQER.QUOTE_ID = #{quoteId}

select distinct aa.* from( SELECT I.COUNTERTRADERNAME countertradername,/*对方交易员*/ I.SETTLDATE settldate, /*首次结算日*/ I.SETTLDATE2 settldate2,/*到期结算日*/ ptl_portfolio.Portfolio_Id portfolioId,/*组合代码*/ ptl_portfolio.portfolio_name portfolioName,/*组合名称*/ I.DELIVERYTYPE deliveryType,/*首次结算方式*/ I.DELIVERYTYPE2 deliveryType2,/*到期结算方式*/ I.trademethod trademethod,/*交易方式*/ I.SETTLCURRENCY settlcurrency,/*结算币种*/ I.EXECTYPE execType,/*成交状态*/ I.OURINSTITUTIONCODE ourinstitutioncode, /*本方*/ I.COUNTERINSTITUTIONCODE counterinstitutioncode,/*对手方*/ I.OURCAPITALBANKNAME ourcapitalbankname, /*资金开户行*/ I.OURCAPITALACCOUNTNAME ourcapitalaccountname, /*资金账户户名*/ I.OURCAPITALACCOUNTNUMBER ourcapitalaccountnumber, /*资金账号*/ I.OURPAYMENTSYSTEMCODE ourpaymentsystemcode, /*支付系统行号*/ I.COUNTERCAPITALACCOUNTNAME countercapitalaccountname, /*对方资金账户户名*/ I.COUNTERCAPITALBANKNAME countercapitalbankname, /*对方资金开户行*/ I.COUNTERCAPITALACCOUNTNUMBER countercapitalaccountnumber, /*对方资金账号*/ I.COUNTERPAYMENTSYSTEMCODE counterpaymentsystemcode, /*对方支付系统行号*/ I.COUNTERDEPOSITACCOUNTNAME counterdepositaccountname, /*对方托管账户户名*/ I.COUNTERDEPOSITINSTITUTION counterdepositinstitution, /*对方托管机构*/ I.COUNTERDEPOSITACCOUNTNUMBER counterdepositaccountnumber, /*对方托管账号*/ I.OURINSTITUTIONCHINESESHORTNAME ourinstitutionchineseshortname,/*本方机构*/ I.INSTITUTIONCHINESESHORTNAME institutionchineseshortname,/*对手方机构*/ I.settlcurrency ccy, /*债券币种*/ 1 as exchangerate, /*汇率*/ iqcp.PLEDGE_RATIO as pledgeRate,/*折算比例%*/ I.clearingmethod as clearingmethod,/*清算类型*/ '' as settleStatus,/*净额清算状态*/ '' as repoMethod,/*回购方式*/ tpda.ENTRUST_ID entrustId, tpd.TRADE_ID tradeId, tpd.F_TRADE_ID fTradeId, tpd.R_TRADE_ID rTradeId, mcci2.PARTY_NAME cpPartyName,/*对手方机构*/ I.OURTRADERNAME ourtradername,/*本方交易员*/ decode(I.BUSINESSTYPE,'BOND', (select TRADE_MARKET from fin_product where FINPROD_market_ID = ts.SECID), 'REPO',decode(tr.market, 'IB', '01', 'SH', '03', 'SZ', '04')) market, decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') settleSpeed,/*清算速度*/ I.ourdepositaccountname ourdepositaccountname, I.EXECID execid /*成交编号*/ ,I.BUSINESSTYPE businesstype /*资产类型*/ ,decode(I.BUSINESSTYPE,'BOND',ts.SECID,'REPO','') securityid /*代码*/ ,decode(I.BUSINESSTYPE, 'BOND', I.SYMBOL, 'REPO', '') symbol /*简称*/ ,nvl(ts.ps,tr.ps) side ,ts.Prinamt prinamt ,tr.Repoamt repoamt ,I.LASTQTY lastqty/*券面总计（万）*/ ,tmi.SUMMATCHNUM lastqtyready
,decode(I.BUSINESSTYPE,'BOND',I.PRICE,'REPO',I.PRICE*100) price/*回购利率*/ ,decode(I.BUSINESSTYPE, 'BOND', I.DIRTYPRICE, 'REPO', '') dirtyprice ,decode(I.BUSINESSTYPE, 'BOND', I.YIELD2*100, 'REPO', '') underlyingyield2 ,I.TRADEDATE tradedate/*成交时间*/ ,decode(I.BUSINESSTYPE, 'BOND', I.ACCRUEDINTERESTAMT, 'REPO', '') accruedinterestamt ,I.ACCRUEDINTERESTTOTALAMT accruedinteresttotalamt/*回购利息*/ ,I.TRADECASHAMT tradecashamt/*交易金额*/ ,decode(I.BUSINESSTYPE, 'BOND', I.SETTLCURRAMT, 'REPO', I.SETTLCURRAMT2) settlcurramt2/*到期结算金额*/ ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.TRADELIMITDAYS) tradelimitdays/*回购期限*/ ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.CASHHOLDINGDAYS) cashholdingdays/*实际占款天数*/ ,ROUND(NVL(decode(I.BUSINESSTYPE, 'BOND', NVL(tmi.SUMMATCHNUM*100, 0), 'REPO', NVL(tmi.SUMMATCHNUM, 0)), 0)/ NVL(DECODE(I.BUSINESSTYPE, 'BOND', I.LASTQTY, 'REPO', I.TRADECASHAMT), 1) , 4) percent, decode(I.BUSINESSTYPE, 'BOND', I.STRIKEYIELD*100, 'REPO', '') strikeyield, CASE WHEN tmi.SUMMATCHNUM IS NULL or tmi.SUMMATCHNUM=0 THEN '02' WHEN decode(I.BUSINESSTYPE, 'BOND', NVL(tmi.SUMMATCHNUM*100, 0), 'REPO', NVL(tmi.SUMMATCHNUM, 0)) = DECODE(I.BUSINESSTYPE, 'BOND', I.LASTQTY, 'REPO', I.TRADECASHAMT) then '01' ELSE '03' END matchStatus,/*匹配状态*/ QUOTE.QUOTEID reference,/*报价编号*/ /*QUOTE.ENTRUST_ID entrustId,*/ I.CB_FPRICE_AMT, I.SC_FPRICE_AMT, case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else COUNTERDEPOSITACCOUNTNUMBER end as ourdepositaccountnumber, su.USER_NAME userName, I.OURDEPOSITINSTITUTION ourdepositinstitution, tpd.FINPROD_ID finprodId, I.TRADETIME tradetime, QUOTE.quote_type quoteType, fpt.TYPE_4 assetTypeOne FROM INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID
LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON I.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID LEFT JOIN SYS_USER_ADD sua ON nvl(ts.TRAD,tr.BUYTRADER) =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID LEFT JOIN ( SELECT SUM(MATCH_NUM) SUMMATCHNUM,CSTP_TRADE_ID FROM trd_match_info group by CSTP_TRADE_ID ) tmi on tmi.CSTP_TRADE_ID = I.EXECID LEFT JOIN ( SELECT i.EXECID ,iqb.create_user,iqb.update_user,iqb.quote_date,listagg(nvl(iqb.ENTRUST_ID , nvl(iqc.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID,iqerr.ENTRUST_ID) )), ',') WITHIN GROUP ( ORDER BY i.UPDATETIME DESC) AS ENTRUST_ID ,nvl(iqb.QUOTE_ID,iqc.QUOTE_ID) QUOTEID,iqc.SETT_TYPE,iqb.quote_type quote_type FROM INTERF_CSTP_TRADE i LEFT JOIN IBU_QUOTE_BOND_DET iqbd ON i.EXECID = iqbd.EXECID LEFT JOIN IBU_QUOTE_BOND iqb ON iqbd.QUOTE_ID = iqb.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE iqerb ON iqb.QUOTE_ID = iqerb.QUOTE_ID LEFT JOIN IBU_QUOTE_CREP iqc ON i.EXECID = iqc.EXECID LEFT JOIN IBU_QUOTE_ETR_RE iqerr ON iqc.QUOTE_ID = iqerr.QUOTE_ID GROUP BY i.EXECID ,nvl(iqb.QUOTE_ID,iqc.QUOTE_ID),iqc.SETT_TYPE,iqb.quote_type,iqb.create_user,iqb.update_user,iqb.quote_date ) QUOTE ON QUOTE.EXECID=I.EXECID left join TRD_PRODUCT_DEAL tpd on I.EXECID = tpd.F_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID left join ETR_ENTRUST on ETR_ENTRUST.ENTRUST_ID = tpda.ENTRUST_ID left join ptl_portfolio on ptl_portfolio.portfolio_id = ETR_ENTRUST.Portfolio_Id left join fin_product fp on fp.finprod_market_id = ts.SECID and fp.finprod_type2 = 'F01' LEFT JOIN FIN_PRODUCT_TYPE fpt ON fp.FINPROD_ID = fpt.FINPROD_ID LEFT JOIN (select a.QUOTE_ID, a.PLEDGE_RATIO, a.PLEDGE_AMT, b.FINPROD_MARKET_ID, b.FINPROD_ABBR from IBU_QUOTE_CREP_PLEDGE a left join FIN_PRODUCT b on b.FINPROD_ID = a.PLEDGE_FINPROD_ID)iqcp ON iqcp.QUOTE_ID = QUOTE.QUOTEID
LEFT JOIN( SELECT T1.PARTY_CUSTOMER_ID, T1.PARTY_NAME FROM MST_CFETS_CUSTOMER_INFO T1 LEFT JOIN MST_CFETS_CUSTOMER_RELA T2 ON T2.MPARTY_ID = T1.PARTY_ID UNION SELECT T1.PARTY_CUSTOMER_ID, T1.PARTY_NAME FROM MST_CFETS_CUSTOMER_INFO T1 LEFT JOIN MST_CFETS_CUSTOMER_RELA T2 ON T2.SPARTY_ID = T1.PARTY_ID) mcci2 on mcci2.PARTY_CUSTOMER_ID = I.COUNTERINSTITUTIONCODE
AND I.BUSINESSTYPE = 'BOND'
AND nvl(ts.ps,tr.ps) = #{ps}
AND (ts.SECID = #{finprodId} or ts.SECID = CONCAT(#{finprodId},'.IB'))
AND I.EXECID IN
#{item}
AND (TRADEDATE BETWEEN #{tradeDateBegin} AND #{tradeDateEnd})
AND to_date(TRADEDATE,'yyyy-mm-dd') >= to_date(#{entrustStartDate},'yyyy-mm-dd') AND to_date(TRADEDATE,'yyyy-mm-dd') <= to_date(#{entrustEndDate},'yyyy-mm-dd')
and I.OURDEPOSITACCOUNTNUMBER = #{secAcctId}
and I.OURTRADERNAME LIKE CONCAT('%',CONCAT(#{ourTradeName},'%'))
and I.TRADELIMITDAYS >=${repoTerm}
and I.TRADELIMITDAYS <= ${repoTerm2}
and I.TRADECASHAMT >=${priceAmt}
and I.TRADECASHAMT <= ${priceAmt2}
and (nvl(iqb.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID ,nvl(iqc.ENTRUST_ID,iqerr.ENTRUST_ID ))) = #{entrustBusiCode} or nvl(iqb.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID ,nvl(iqc.ENTRUST_ID,iqerr.ENTRUST_ID ))) is null )
and QUOTE.quoteId = #{quoteId}
and ts.SECID = #{entrustFinprodId}
and decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED) = #{entrustSettleSpeed}
and nvl(ts.ps,tr.ps) = #{entrustPs}
and I.TRADELIMITDAYS = #{entrustTradelimitdays}
and QUOTE.quote_type = #{quoteType}
and to_date(I.SETTLDATE,'YYYYMMDD') = to_date(#{quaryDate},'YYYY-MM-DD')
and (QUOTE.CREATE_USER = #{loginUserId,jdbcType=VARCHAR} or QUOTE.UPDATE_USER = #{loginUserId,jdbcType=VARCHAR} or QUOTE.UPDATE_USER is null )
) aa
AND aa.matchStatus IN
#{item}
and aa.market = #{tradeMarket}
and aa.settleSpeed = #{settleSpeed}
and aa.tradelimitdays = #{tradelimitdays}
and aa.side = #{benfangSide}
order by decode(aa.matchStatus,'02',1,'03',2,'01',3,4)

SELECT SUM(SHARE_AMT*100) FROM ( SELECT SHARE_AMT FROM WFL_IBU_QUOTE_ETR_RE T1 WHERE EXISTS ( SELECT * FROM WFL_IBU_QUOTE_BOND2 T2 WHERE T2.QUOTE_ID = T1.QUOTE_ID AND T2.ENTRUST_ID IS NULL)
and T1.ENTRUST_ID = #{entrustId}
and T1.WORKFLOW_ID != #{workflowId}
UNION ALL SELECT SHARE_AMT FROM WFL_IBU_QUOTE_BOND2 T3
and T3.ENTRUST_ID = #{entrustId}
and T3.WORKFLOW_ID != #{workflowId}
)
